// Patch is a property with patch semantics: absent leaves the stored value
// unchanged, null clears it, and a value replaces it. The zero value is absent.
// A field of this type is tagged omitzero, so an absent one is not sent; a null
// one is sent as null. A value is sent as T encodes, so a value holding a nil
// slice or map is sent as null: send an empty one for [] or {}. Where the schema
// says so, as for a compaction's summary, an empty value also clears.
type Patch[T any] struct {
	present bool
	null    bool
	value   T
}

// PatchValue returns a Patch that replaces the stored value with v.
func PatchValue[T any](v T) Patch[T] {
	return Patch[T]{
		present: true,
		value:   v,
	}
}

// PatchNull returns a Patch that clears the stored value: it is sent as null.
func PatchNull[T any]() Patch[T] {
	return Patch[T]{
		present: true,
		null:    true,
	}
}

// IsZero reports whether p is absent: the stored value is left unchanged.
func (p Patch[T]) IsZero() bool {
	return !p.present
}

// IsNull reports whether p is null: the stored value is cleared.
func (p Patch[T]) IsNull() bool {
	return p.present && p.null
}

// Value returns the value p replaces the stored value with, and whether it
// holds one.
func (p Patch[T]) Value() (T, bool) {
	return p.value, p.present && !p.null
}

// MarshalJSON encodes p's value, or null when p is null or absent.
func (p Patch[T]) MarshalJSON() ([]byte, error) {
	if !p.present || p.null {
		return []byte("null"), nil
	}
	return json.Marshal(p.value)
}

// UnmarshalJSON decodes null as a null p and anything else as a value.
func (p *Patch[T]) UnmarshalJSON(b []byte) error {
	if string(b) == "null" {
		*p = PatchNull[T]()
		return nil
	}
	var v T
	if err := json.Unmarshal(b, &v); err != nil {
		return err
	}
	*p = PatchValue(v)
	return nil
}

// objectKeys decodes b as a JSON object, folds the required keys as foldKeys
// does, and fails, naming typ and the key, when a required key is absent. JSON
// null is an object without keys.
func objectKeys(b []byte, typ string, required ...string) (map[string]json.RawMessage, error) {
	var m map[string]json.RawMessage
	if err := json.Unmarshal(b, &m); err != nil {
		return nil, fmt.Errorf("%s: %w", typ, err)
	}
	foldKeys(b, m, required...)
	for _, k := range required {
		if _, ok := m[k]; !ok {
			return nil, fmt.Errorf("%s: missing required property %q", typ, k)
		}
	}
	return m, nil
}

// foldKeys makes m, the keys of the JSON object b, hold for each of names the
// value encoding/json gives a struct field of that name: the value of the last key
// of b that matches it under Unicode case folding. It removes the other matching
// keys and keeps every key no name matches.
func foldKeys(b []byte, m map[string]json.RawMessage, names ...string) {
	for _, name := range names {
		var keys []string
		for k := range m {
			if strings.EqualFold(k, name) {
				keys = append(keys, k)
			}
		}
		if len(keys) == 0 || len(keys) == 1 && keys[0] == name {
			continue
		}
		last := keys[0]
		if len(keys) > 1 {
			last = lastKey(b, name)
		}
		v := m[last]
		for _, k := range keys {
			delete(m, k)
		}
		m[name] = v
	}
}

// lastKey returns the last key of the JSON object b that matches name under
// Unicode case folding. b has decoded as an object already.
func lastKey(b []byte, name string) string {
	d := json.NewDecoder(bytes.NewReader(b))
	var last string
	if _, err := d.Token(); err != nil {
		return last
	}
	for d.More() {
		t, err := d.Token()
		if err != nil {
			return last
		}
		if k, ok := t.(string); ok && strings.EqualFold(k, name) {
			last = k
		}
		var v json.RawMessage
		if err := d.Decode(&v); err != nil {
			return last
		}
	}
	return last
}

// orZero decodes raw into a T, or returns the zero T when raw is empty or does
// not decode.
func orZero[T any](raw json.RawMessage) T {
	var v T
	if len(raw) > 0 && json.Unmarshal(raw, &v) == nil {
		return v
	}
	var zero T
	return zero
}

// orDefault decodes raw into a T, or returns def, the schema default, when raw
// is empty or does not decode.
func orDefault[T any](raw json.RawMessage, def T) T {
	var v T
	if len(raw) > 0 && json.Unmarshal(raw, &v) == nil {
		return v
	}
	return def
}

// skipInvalid decodes raw as a JSON array, dropping the items that do not decode
// into a T. An empty raw value or null is no items.
func skipInvalid[T any](raw json.RawMessage) ([]T, error) {
	if len(raw) == 0 {
		return nil, nil
	}
	var items []json.RawMessage
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil, err
	}
	if items == nil {
		return nil, nil
	}
	out := make([]T, 0, len(items))
	for _, it := range items {
		var v T
		if json.Unmarshal(it, &v) == nil {
			out = append(out, v)
		}
	}
	return out, nil
}

// patchOf reads a patch property's raw value: empty is absent, null is null, a
// value that decodes into a T is that value, and one that does not is absent.
func patchOf[T any](raw json.RawMessage) Patch[T] {
	if len(raw) == 0 {
		return Patch[T]{}
	}
	if string(raw) == "null" {
		return PatchNull[T]()
	}
	var v T
	if json.Unmarshal(raw, &v) != nil {
		return Patch[T]{}
	}
	return PatchValue(v)
}

// patchItems is patchOf for an array, dropping the items that do not decode
// into a T, as skipInvalid does.
func patchItems[T any](raw json.RawMessage) Patch[[]T] {
	if len(raw) == 0 {
		return Patch[[]T]{}
	}
	if string(raw) == "null" {
		return PatchNull[[]T]()
	}
	items, err := skipInvalid[T](raw)
	if err != nil {
		return Patch[[]T]{}
	}
	return PatchValue(items)
}

// absentIfNull returns raw, or nil when raw is the JSON null: a null raw value
// is an absent one, as ACP v1 defines it for rawInput and rawOutput.
func absentIfNull(raw json.RawMessage) json.RawMessage {
	if string(raw) == "null" {
		return nil
	}
	return raw
}

// mergeObject adds the keys of x's JSON object that b's object lacks: the keys of
// a flattened member. Values stay raw JSON, so numbers keep every digit.
func mergeObject(b []byte, x any) ([]byte, error) {
	var m map[string]json.RawMessage
	if err := json.Unmarshal(b, &m); err != nil {
		return nil, err
	}
	xb, err := json.Marshal(x)
	if err != nil {
		return nil, err
	}
	var xm map[string]json.RawMessage
	if err := json.Unmarshal(xb, &xm); err != nil {
		return nil, err
	}
	for k, v := range xm {
		if _, ok := m[k]; !ok {
			m[k] = v
		}
	}
	return json.Marshal(m)
}

// keyOrder returns the keys of the JSON object raw in the order they appear, each
// once at its first appearance, or nil when raw is empty, null, or not an object.
func keyOrder(raw json.RawMessage) []string {
	d := json.NewDecoder(bytes.NewReader(raw))
	if t, err := d.Token(); err != nil || t != json.Delim('{') {
		return nil
	}
	var keys []string
	for d.More() {
		t, err := d.Token()
		k, ok := t.(string)
		var x json.RawMessage
		if err != nil || !ok || d.Decode(&x) != nil {
			return keys
		}
		if !slices.Contains(keys, k) {
			keys = append(keys, k)
		}
	}
	return keys
}

// orderedObject encodes m as a JSON object whose keys are the names of order that
// m holds, in that order and each once, then m's other keys, sorted.
func orderedObject[V any](m map[string]V, order []string) (json.RawMessage, error) {
	keys := make([]string, 0, len(m))
	for _, k := range order {
		if _, ok := m[k]; ok {
			if !slices.Contains(keys, k) {
				keys = append(keys, k)
			}
		}
	}
	for _, k := range slices.Sorted(maps.Keys(m)) {
		if !slices.Contains(keys, k) {
			keys = append(keys, k)
		}
	}
	b := []byte("{")
	for i, k := range keys {
		if i > 0 {
			b = append(b, ',')
		}
		kb, err := json.Marshal(k)
		if err != nil {
			return nil, err
		}
		vb, err := json.Marshal(m[k])
		if err != nil {
			return nil, err
		}
		b = append(b, kb...)
		b = append(b, ':')
		b = append(b, vb...)
	}
	return append(b, '}'), nil
}

// Negotiation is what initialize agreed on a connection: the request the
// client sent and the response the agent answered
// (0017-MADR-remediate-acp-v1-conformance-violations.md, G1 and N1).
type Negotiation struct {
	Request  InitializeRequest
	Response InitializeResponse
}

// Allows reports whether the capabilities n records let method be sent: nil,
// or a *CapabilityError naming the capability that is not advertised
// (0017-MADR-remediate-acp-v1-conformance-violations.md, G1).
func (n Negotiation) Allows(method string) error {
	switch method {
	case AgentMethodLogout:
		if n.Response.AgentCapabilities.Auth.Logout == nil {
			return &CapabilityError{
				Method:     method,
				Capability: "auth.logout",
			}
		}
	case AgentMethodSessionClose:
		if n.Response.AgentCapabilities.SessionCapabilities.Close == nil {
			return &CapabilityError{
				Method:     method,
				Capability: "sessionCapabilities.close",
			}
		}
	case AgentMethodSessionDelete:
		if n.Response.AgentCapabilities.SessionCapabilities.Delete == nil {
			return &CapabilityError{
				Method:     method,
				Capability: "sessionCapabilities.delete",
			}
		}
	case AgentMethodSessionFork:
		if n.Response.AgentCapabilities.SessionCapabilities.Fork == nil {
			return &CapabilityError{
				Method:     method,
				Capability: "sessionCapabilities.fork",
			}
		}
	case AgentMethodSessionList:
		if n.Response.AgentCapabilities.SessionCapabilities.List == nil {
			return &CapabilityError{
				Method:     method,
				Capability: "sessionCapabilities.list",
			}
		}
	case AgentMethodSessionLoad:
		if !n.Response.AgentCapabilities.LoadSession {
			return &CapabilityError{
				Method:     method,
				Capability: "loadSession",
			}
		}
	case AgentMethodSessionResume:
		if n.Response.AgentCapabilities.SessionCapabilities.Resume == nil {
			return &CapabilityError{
				Method:     method,
				Capability: "sessionCapabilities.resume",
			}
		}
	case ClientMethodElicitationComplete:
		if n.Request.ClientCapabilities.Elicitation == nil || n.Request.ClientCapabilities.Elicitation.Url == nil {
			return &CapabilityError{
				Method:     method,
				Capability: "elicitation.url",
			}
		}
	case ClientMethodFsReadTextFile:
		if !n.Request.ClientCapabilities.Fs.ReadTextFile {
			return &CapabilityError{
				Method:     method,
				Capability: "fs.readTextFile",
			}
		}
	case ClientMethodFsWriteTextFile:
		if !n.Request.ClientCapabilities.Fs.WriteTextFile {
			return &CapabilityError{
				Method:     method,
				Capability: "fs.writeTextFile",
			}
		}
	case ClientMethodTerminalCreate, ClientMethodTerminalKill, ClientMethodTerminalOutput, ClientMethodTerminalRelease, ClientMethodTerminalWaitForExit:
		if !n.Request.ClientCapabilities.Terminal {
			return &CapabilityError{
				Method:     method,
				Capability: "terminal",
			}
		}
	}
	return nil
}

// gater is a value that holds a property or variant the capabilities gate.
type gater interface {
	gates(n *Negotiation, method string) error
}

// gateMessage checks a typed message against the record n of initialize:
// initialize itself passes; before it, nothing does; after it, a method the
// record does not allow does not, nor a property or variant it does not.
func gateMessage(n *Negotiation, method string, params any) error {
	if method == AgentMethodInitialize {
		return nil
	}
	if n == nil {
		return fmt.Errorf("%s: %w", method, ErrNotInitialized)
	}
	if err := n.Allows(method); err != nil {
		return err
	}
	if g, ok := params.(gater); ok {
		return g.gates(n, method)
	}
	return nil
}

// gateResult checks a result of method against the property and variant
// gates of the record n; the method itself was checked when the request was
// sent or received (0017-MADR-remediate-acp-v1-conformance-violations.md, G1).
func gateResult(n *Negotiation, method string, result any) error {
	if g, ok := result.(gater); ok && n != nil {
		return g.gates(n, method)
	}
	return nil
}

func (v *AuthenticateRequest) gates(n *Negotiation, method string) error {
	for _, a := range n.Response.AuthMethods {
		if a.Terminal != nil && a.Terminal.Id == v.MethodId {
			return fmt.Errorf("%s: methodId %q: %w", method, v.MethodId, ErrTerminalAuthMethod)
		}
	}
	return nil
}

func (v *ConfigOptionUpdate) gates(n *Negotiation, method string) error {
	for i := range v.ConfigOptions {
		if err := v.ConfigOptions[i].gates(n, method); err != nil {
			return err
		}
	}
	return nil
}

func (u *CreateElicitationRequest) gates(n *Negotiation, method string) error {
	if u.Form != nil && (n.Request.ClientCapabilities.Elicitation == nil || n.Request.ClientCapabilities.Elicitation.Form == nil) {
		return &CapabilityError{
			Method:     method,
			Capability: "elicitation.form",
			Variant:    "form",
		}
	}
	if u.Url != nil && (n.Request.ClientCapabilities.Elicitation == nil || n.Request.ClientCapabilities.Elicitation.Url == nil) {
		return &CapabilityError{
			Method:     method,
			Capability: "elicitation.url",
			Variant:    "url",
		}
	}
	if u.Other != nil {
		return &CapabilityError{
			Method:     method,
			Capability: "elicitation." + u.Other.Mode,
			Variant:    u.Other.Mode,
		}
	}
	return nil
}

